Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Bioimurization Cast/Mold','Mold/Cast formed by an encrusting organism (expected to be paired with a body fossil part for the encrusting organism).  Consult Curatorial Associate prior to using this attribute.');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Authigenic nodule','Mineralized nodule containing fossil. Example: Wardie, Scotland nodules, Mazon Creek nodules.
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Carbonization/Coalifiction','Organic material preserved as carbon. Example: graptolites, compressed insect from Florissant.');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Entrapment','Original organic material preserved within amber or asphalt. Example: organisms in amber.');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Not otherwise specified','Indeterminate body fossil; could be permineralized, replaced, recrystallized, unaltered, etc. Consult Curatorial Associate prior to using this attribute.
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Permineralized','Voids in skeletal material filled with minerals. Example: petrified bone.');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Replacement/Recrystallization','Original hard parts replaced by other minerals. If determinable, note in remarks the mineral that replaced the original fossil or the mineral recrystallized form. Example: silicified Glass Mountains brachiopods, pyritized fossils.
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Soft tissue','Soft parts preserved either in isolation or associated with hard parts. Example: bird feather impressions, dinosaur bone with skin impressions, jellyfish, mammoth hair.');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Body fossil: Unaltered remains','Original hard or soft tissue (bone, shell, teeth, hair) without significant chemical change, such as mineralization or replacement. Example: mammoth hair, some cave fossils');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Cast/Mold/Steinkern','Direct impression in matrix or 3-dimensional (mold), natural cast of fossil from sediment fill where a fossil used to be (external cast), or a 3-dimensional, natural cast formed from sediment filling the internal cavity of a hollow organism (internal cast/steinkern). Note in the attribute''s remarks which one the fossil is. Example: bone cast, bivalve steinkern');
Insert into CTFOSSILIZATION_TYPE (FOSSILIZATION_TYPE,DESCRIPTION) values ('Ichnofossil','Fossil record of biological activity without preserved biological remains. Example: trackway, coprolite.');
